"""Apollo R183 source-controlled, reproducible unpublished Evidence Atlas.

Embedded material is compressed UTF-8 HTML authored for staging research, NOT NASA image bytes. Regenerate a readable HTML artifact locally; do not install or publish without a reviewed WP release.
"""
from pathlib import Path
import argparse,base64,hashlib,zlib
EXPECTED_SHA256="dd09aaeefa1326d2c1ab42d7084a6525a048c167e7de8e013f53c930486b2b27"
PAYLOAD=""

def reconstruct(destination:Path)->str:
    data=zlib.decompress(base64.b64decode(PAYLOAD,validate=True))
    actual=hashlib.sha256(data).hexdigest()
    if actual != EXPECTED_SHA256: raise ValueError("Apollo source SHA256 mismatch; refusing artifact")
    destination.parent.mkdir(parents=True,exist_ok=True)
    destination.write_bytes(data)
    return actual

if __name__=="__main__":
    p=argparse.ArgumentParser();p.add_argument("--output",type=Path,default=Path("atlas.html"))
    print(reconstruct(p.parse_args().output))
